// useKnowledgeGraph (#2856) — the Algorithms page's live graph. Starts on the packaged seed for an
// instant first paint, then hydrates from the writable store (`bsc graph dump`, #2853) so the knowledge
// librarian's `bsc graph set`/`link`/`remove` edits show — polled, since the page is kept-mounted and a
// live session can curate at any time. The seed is the fallback (persist/seed = cache, the store is the
// source of truth — the golden rule); a degraded environment (web shell, tests, old `bsc`) just keeps
// the seed because `loadGraph` returns null.
import { useRef, useState } from "react";
import { usePoll } from "@/shared/hooks/usePoll";
import { KNOWLEDGE, type KnowledgeGraph } from "@/features/algorithms/lib/knowledge";
import { loadGraph, loadGraphSig } from "@/features/algorithms/lib/graphBridge";

/** How often to re-read the store. The dump is a fast local read; the librarian edits show within a tick. */
const HYDRATE_MS = 5000;

/** An order-independent content signature — so an unchanged store (serde may reorder JSON keys) does NOT
 *  churn a re-render every tick, while any implementation edit does. */
function graphSig(g: KnowledgeGraph): string {
  return g.implementations
    .map((im) => `${im.id}:${im.tech}:${im.role}:${im.name}:${im.summary ?? ""}:${im.composes.join(",")}`)
    .sort()
    .join("|");
}
const SEED_SIG = graphSig(KNOWLEDGE);

/** Which copy the caller is looking at. `seed` is the PACKAGED fallback — correct-looking and
 *  incomplete — and a page showing it must say so. */
export type GraphSource = "seed" | "store";

/** The live knowledge graph: the seed, hydrated + kept fresh from the writable store.
 *
 *  # It reports its SOURCE, and that is not cosmetic
 *
 *  The fallback is silent by construction: `loadGraph` returns null on any failure and this hook keeps
 *  the seed, so a broken hydrate renders a graph that looks entirely correct and is a third the size.
 *  MEASURED: the seed carries 758 records and 36 under `crates/`, the writable store 1,403 and 542. The
 *  only way anyone — a user or the person debugging it — could tell the two apart was to count rows and
 *  know what the counts should be. Two separate faults hid behind that, each for hours.
 *
 *  So the hook answers WHICH copy it is handing back, and the page says so on screen. */
export function useKnowledgeGraph(): { graph: KnowledgeGraph; source: GraphSource } {
  const [graph, setGraph] = useState<KnowledgeGraph>(KNOWLEDGE);
  // Has a read of the writable store ever landed? Starts false — the first paint IS the seed.
  const [source, setSource] = useState<GraphSource>("seed");
  // The signature currently rendered — start on the seed so a store that still equals the seed never
  // triggers a redundant swap; only a real edit does.
  const appliedSig = useRef(SEED_SIG);
  // The STORE's signature as of the last successful hydrate. Distinct from `appliedSig`, which signs
  // the RENDERED model: this one answers "is the store still what I read", and it is what lets a tick
  // end without transferring a document at all.
  const storeSig = useRef<string | null>(null);
  usePoll(
    async (isCancelled) => {
      // ASK BEFORE FETCHING. This poll used to pull the whole document every 5 seconds and compare
      // afterwards — 50.72 MB per tick, MEASURED 2026-09-08, against a page that renders 0.93 MB of it.
      // When that transfer failed, `loadGraph` returned null and this hook kept the packaged seed, so
      // the graph quietly showed 757 records instead of 1,401 and nothing said so.
      const sig = await loadGraphSig();
      if (isCancelled()) return;
      // `null` is CANNOT TELL, not "unchanged" — fall through to the full read, or an error would
      // freeze the page on whatever it last rendered.
      if (sig !== null && sig === storeSig.current) return;

      const g = await loadGraph();
      if (isCancelled() || !g) return; // unreachable / old bsc → keep the current graph
      storeSig.current = sig;
      // The READ LANDED, even if the content matches the seed — that is what `source` reports, and it
      // is deliberately set before the no-change return below. A store that happens to equal the seed
      // is hydrated; only a store we could not READ is not.
      setSource("store");
      const applied = graphSig(g);
      if (applied === appliedSig.current) return; // no change → no re-render
      appliedSig.current = applied;
      setGraph(g);
    },
    HYDRATE_MS,
  );
  return { graph, source };
}

