import { describe, it, expect, vi, beforeEach } from "vitest";
import { act, renderHook, waitFor } from "@testing-library/react";

const loadGraph = vi.fn();
const loadGraphSig = vi.fn();
vi.mock("@/features/algorithms/lib/graphBridge", () => ({
  loadGraph: () => loadGraph(),
  loadGraphSig: () => loadGraphSig(),
}));

// CAPTURE THE POLL CALLBACK so a test can drive TICKS instead of waiting for them. The interval is
// 5s; a test that renders the hook and then awaits a macrotask observes exactly ONE tick, so any
// assertion about what the SECOND tick does is vacuous — which is how the first version of the
// short-circuit test below passed against a hook with the short-circuit deleted.
let tick: ((isCancelled: () => boolean) => Promise<void>) | null = null;
vi.mock("@/shared/hooks/usePoll", () => ({
  usePoll: (fn: (isCancelled: () => boolean) => Promise<void>) => {
    tick = fn;
  },
}));

import { useKnowledgeGraph } from "@/features/algorithms/useKnowledgeGraph";
import { KNOWLEDGE } from "@/features/algorithms/lib/knowledge";

describe("useKnowledgeGraph (#2856)", () => {
  // Block body, not the concise arrow — see graphBridge.test.ts (#3390): `mockReset()` returns the mock,
  // which vitest then runs as an after-each teardown. Harmless while every test here resolves, but it is
  // the same landmine that silently failed the sibling suite the moment one test rejected.
  beforeEach(() => {
    loadGraph.mockReset();
    // DEFAULT TO "CANNOT TELL". Every pre-existing test below was written before the signature
    // short-circuit and asserts what `loadGraph` returns, so the default has to be the value that
    // still reaches it — which is the same null-means-fall-through rule the hook itself follows.
    loadGraphSig.mockReset();
    loadGraphSig.mockResolvedValue(null);
  });

  it("starts on the packaged seed (instant first paint), and keeps it when the bridge is unreachable", () => {
    loadGraph.mockResolvedValue(null);
    const { result } = renderHook(() => useKnowledgeGraph());
    expect(result.current.graph).toBe(KNOWLEDGE);
  });

  it("swaps to the store's graph when it differs from the seed (a librarian edit shows)", async () => {
    loadGraph.mockResolvedValue({
      implementations: [
        ...KNOWLEDGE.implementations,
        { id: "rust.skiplist", tech: "rust", role: "primitive", name: "SkipList", composes: [], code: "// skip list" },
      ],
    });
    const { result } = renderHook(() => useKnowledgeGraph());
    await act(async () => { await tick!(() => false); });
    await waitFor(() => expect(result.current.graph.implementations.some((im) => im.id === "rust.skiplist")).toBe(true));
  });

  it("keeps the seed identity when the store still matches it (no needless swap/re-render)", async () => {
    loadGraph.mockResolvedValue(KNOWLEDGE);
    const { result } = renderHook(() => useKnowledgeGraph());
    await act(async () => { await tick!(() => false); });
    expect(result.current.graph).toBe(KNOWLEDGE); // sig matched the seed → never re-set
  });

  // ── the signature short-circuit (#the-algorithms-page-hydrates-fifty-megabytes-every-five-seconds) ──

  it("does not transfer a document when the store's signature has not changed", async () => {
    // THE WHOLE POINT. This poll used to pull the entire store every 5 seconds and compare afterwards —
    // MEASURED at 50.72 MB per tick against a page that renders 0.93 MB of it — and when that transfer
    // failed the hook silently kept the packaged seed. Asking for the signature first makes the common
    // case (nothing changed) cost nothing.
    loadGraphSig.mockResolvedValue("sig-1");
    loadGraph.mockResolvedValue(KNOWLEDGE);
    renderHook(() => useKnowledgeGraph());

    // Tick one: no signature is held yet, so it cannot know the store is current — it must read.
    await act(async () => { await tick!(() => false); });
    expect(loadGraph).toHaveBeenCalledTimes(1);

    // Ticks two and three: same signature, so NO document may cross.
    await act(async () => { await tick!(() => false); });
    await act(async () => { await tick!(() => false); });
    expect(loadGraph, "an unchanged signature must not fetch the document again").toHaveBeenCalledTimes(1);
    expect(loadGraphSig).toHaveBeenCalledTimes(3);
  });

  it("fetches again as soon as the signature moves", async () => {
    // The other half: the short-circuit must not become a freeze. A librarian edit changes the
    // signature, and the very next tick must read the document.
    loadGraphSig.mockResolvedValue("sig-1");
    loadGraph.mockResolvedValue(KNOWLEDGE);
    renderHook(() => useKnowledgeGraph());
    await act(async () => { await tick!(() => false); });
    await act(async () => { await tick!(() => false); });
    expect(loadGraph).toHaveBeenCalledTimes(1);

    loadGraphSig.mockResolvedValue("sig-2");
    await act(async () => { await tick!(() => false); });
    expect(loadGraph).toHaveBeenCalledTimes(2);
  });

  it("treats an unreadable signature as CANNOT TELL and still reads the store", async () => {
    // `null` must never be taken for "unchanged". If it were, one failed signature read would freeze
    // the page on whatever it last rendered and no later edit would ever appear.
    loadGraphSig.mockResolvedValue(null);
    loadGraph.mockResolvedValue(KNOWLEDGE);
    renderHook(() => useKnowledgeGraph());
    await act(async () => { await tick!(() => false); });
    await act(async () => { await tick!(() => false); });
    expect(loadGraph, "cannot-tell must fall through to a full read, every time").toHaveBeenCalledTimes(2);
  });

  // ── the source is REPORTED, not inferred (#the-algorithms-page-says-which-store-it-is-showing) ──

  it("says `seed` until a read of the writable store lands", async () => {
    // The fallback is silent by construction: a failed hydrate keeps the packaged seed and renders a
    // graph that looks entirely correct and is a third the size (758 records against 1,403; 36 under
    // crates/ against 542). Nothing on screen distinguished them, and two separate faults hid behind
    // that for hours. The page can only say so if the hook tells it.
    loadGraphSig.mockResolvedValue(null);
    loadGraph.mockResolvedValue(null);
    const { result } = renderHook(() => useKnowledgeGraph());
    expect(result.current.source).toBe("seed");
    await act(async () => { await tick!(() => false); });
    expect(result.current.source, "a failed read must NOT read as hydrated").toBe("seed");
  });

  it("says `store` once a read lands, even when the content equals the seed", async () => {
    // A store that happens to match the seed IS hydrated — only a store we could not READ is not.
    // Reporting that case as `seed` would leave the notice up permanently on a healthy install.
    loadGraph.mockResolvedValue(KNOWLEDGE);
    const { result } = renderHook(() => useKnowledgeGraph());
    await act(async () => { await tick!(() => false); });
    expect(result.current.source).toBe("store");
    expect(result.current.graph).toBe(KNOWLEDGE);
  });
});
